struct Particle {
    uint16_t hash;
};

uint32_t* createNeighborTable(Particle *sortedParticles, const size_t &particleCount) {
    if (particleCount == 0) {
        return new uint32_t[1](); // Return empty table
    }

    // Find maximum hash value to determine table size
    uint16_t maxHash = 0;
    for (size_t i = 0; i < particleCount; ++i) {
        maxHash = std::max(maxHash, sortedParticles[i].hash);
    }

    // Create hash table with size maxHash + 1
    uint32_t* hashTable = new uint32_t[maxHash + 1];

    // Initialize all entries to indicate no particles
    for (uint32_t i = 0; i <= maxHash; ++i) {
        hashTable[i] = static_cast<uint32_t>(-1);
    }

    // Since particles are sorted by hash, we can efficiently fill the table
    uint16_t currentHash = sortedParticles[0].hash;
    hashTable[currentHash] = 0;

    for (size_t i = 1; i < particleCount; ++i) {
        if (sortedParticles[i].hash != currentHash) {
            currentHash = sortedParticles[i].hash;
            hashTable[currentHash] = static_cast<uint32_t>(i);
        }
    }

    return hashTable;
}

